using GameFinder.Common;
using OpenAI;
using OpenAI.Chat;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace FrankyCLI.questgen_tools
{
    public class AITools
    {
        private static readonly ChatClient _chatClient;
        private static readonly List<ChatMessage> _history = new();

        // We can turn off the chatgpt calls for fast generation.
        public static bool AIMODE = true;

        static AITools()
        {
            var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                         ?? throw new InvalidOperationException("OPENAI_API_KEY not set");

            var client = new OpenAIClient(apiKey);
            _chatClient = client.GetChatClient("gpt-5.1");

            // Optional: seed with a system prompt so the model knows its role
            _history.Add(new SystemChatMessage(
                GetBackgroundPrompt()
            ));
        }

        public static string TestPrompt()
        {
            string prompt = File.ReadAllText("aipromt.txt");

            string results = RunPrompt(prompt);
            Console.WriteLine(results);

            return results;
        }

        public static bool ExportConversation()
        {
            var loc = Guid.NewGuid().ToString().Substring(0, 8) + ".txt";

            string conversation = "";

            foreach (var item in _history)
            {
                if (item is UserChatMessage)
                {
                    conversation += "USER:" +  ((UserChatMessage)item).Content[0].Text.ToString();
                }
                if (item is SystemChatMessage)
                {
                    conversation += "USER:" + ((SystemChatMessage)item).Content[0].Text.ToString();
                }
                if (item is AssistantChatMessage)
                {
                    conversation += "AI:" + ((AssistantChatMessage)item).Content[0].Text.ToString();
                }
                conversation += Environment.NewLine;
            }

            try
            {
                // Create or overwrite the file with the specified content.
                File.WriteAllText(loc, conversation);

                Console.WriteLine("String successfully written to " + loc);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error writing to " + ex.Message);
            }
            return true;
        }

        // Make sure to set your API key in an environment variable: OPENAI_API_KEY
        public static string RunPrompt(string prompt)
        {
            //Dumb switch for fast testing
            if (!AIMODE)
            {
                return Guid.NewGuid().ToString().Substring(0, 8);
            }

            // 1. Add user message to history
            _history.Add(new UserChatMessage(prompt));

            // 2. Call the model with the full history
            var res = _chatClient.CompleteChat(_history);

            // 3. Get the assistant’s reply text
            string textres = res.Value.Content[0].Text;

            // 4. Do your existing cleanup
            textres = textres.Replace(" — ", " "); // No EM-dashes with spaces
            textres = textres.Replace("—", "");    // No EM-dashes
            textres = textres.Replace("“", "\"");  // Weird quotes
            textres = textres.Replace("”", "\"");
            textres = textres.Replace("’", "'");

            // 5. Add assistant reply back into history so context is preserved
            _history.Add(new AssistantChatMessage(textres));

            return textres;
        }



        public static string GetBackgroundPrompt()
        {
            string result = "";
            result += "You are a Starfield quest writer crafting an in-game mission narrative.\r\n\r\n";


            result += "Include newline characters in your response if there are mulitple sentences.\r\n";
            result += "Don't use the folowing characters: — \r\n";

            result += "The following is background information about the universe the story is set in, don't quote any back directly.\r\n\r\n";

            result += "By the year 2330, humanity has expanded into a region of space known as the Settled Systems \r\n. The technology level is advanced yet grounded: interstellar travel relies on Grav Drives that enable faster-than-light jumps \r\n";

            result += "Within this frontier, major factions vie for power. The United Colonies (UC) – a centralized republic founded in 2161 – is the largest and most militarily powerful human government, projecting an idealized “future of space republic” with its capital at New Atlantis on Jemison (Alpha Centauri)\r\n ";

            result += "The Freestar Collective, a loose confederation of three star systems (Cheyenne, Volii, and Narion) with its capital in Akila City; founded on principles of personal freedom and individuality, this faction embodies a more libertarian, frontier spirit\r\n ";
            result += "The UC and Freestar Collective fought a bloody Colony War two decades ago, and though a treaty ended open conflict, an uneasy tension persists between them\r\n ";

            result += "Beyond these two superpowers, the Settled Systems contends with lawless elements. The Crimson Fleet – a notorious coalition of space pirates – operates as a loose alliance of pirate captains under one banner, originating from the Kryx system and now extending its raids into multiple sectors (even establishing footholds in systems like Sagan, Cheyenne, and Narion)\r\n ";

            result += "Meanwhile, the secretive House Va’ruun lurks on the fringes: a fanatical theocracy of zealots worshipping the Great Serpent, known for violently imposing its faith on non-believers\r\n ";

            //Locations
            result += "New Atlantis was founded on the planet Jemison in 2156, the same year that humans first arrived in the Alpha Centauri system and confirmed that Jemison was a habitable world and suitable for colonization. The original colony was constructed underground on the edge of a plateau, beneath where the first colony ship, the Galileo, made landfall. The site was chosen to take advantage of a natural waterfall to generate hydroelectric power, and in later years, this district would become known as The Well. In 2160, Jemison was determined to be safe enough, and the colony's need for expansion to house evacuees from Earth pressing enough, that construction of residential and commercial structures on the planet's surface was approved and got underway. The United Colonies designated New Atlantis as its capital in 2161.[3][4]\r\n\r\nIn 2330, New Atlantis is the largest and most populous colony in the Settled Systems. The MAST Building, headquarters of the UC government, dominates the skyline, and is flanked by the skyscrapers of the Residential and Commercial districts. The central MAST District includes the MAST Building, embassies of the Freestar Collective and House Va'ruun, a sprawling park, and The Lodge, which is the headquarters of the private exploration group Constellation. The Spaceport sits below the city proper at the foot of the cliffs, and is connected to it by the New Atlantis Transit network";
            result += "The pleasure city of Neon was originally a fishing platform constructed on Volii Alpha by Xenofresh Fisheries. The corporation discovered that the planet's native Chasmbass produced a substance with psychotropic effects, and decided to switch the entire operation to creating the drug Aurora and selling it on the platform.[1] This put Neon on the map, and in 2187 the fishing platform revamped itself into a full-fledged colony dedicated to tourism and commerce. When the Volii system joined the Freestar Collective in 2189, Neon alone retained the rights to produce and sell Aurora, while the drug was criminalized everywhere else in the Settled Systems.\r\n\r\nIn 2232, Phylicia Corbin founded Generdyne Corporation to construct the Conduction Grid over Neon, an undertaking that required almost 25 years to complete. Also known as “the Span”, Neon's Conduction Grid has a unique electromagnetic absorption system that converts lightning strikes into energy that is then stored within power cells in Neon's Underbelly for later distribution. No other city in the Settled Systems has a Conduction Grid, as the structure requires a lightning-rich environment like that found on Volii Alpha in order to function effectively.\r\n\r\nRyujin Industries, which grew into the Settled Systems' most powerful megacorporation in only four years thanks to the invention of its flagship product, the neuroamp, finished construction of its Ryujin Tower headquarters in Neon in 2311. It was built on the opposite end of the platform from the Trade Tower, where Xenofresh Fisheries and other major businesses are based.\r\n\r\nIn 2330, Neon is the largest commercial hub in the Settled Systems, as well as a popular tourist destination due to the legal Aurora trade. Xenofresh Fisheries retains full ownership of the platform, and Xenofresh CEO Benjamin Bayu holds the position of Administrator of Neon, giving him absolute authority over the city's laws. Neon's security service ruthlessly guards the city's status as the sole legitimate purveyor of Aurora, and anyone caught attempting to smuggle any amount of Aurora outside the city will receive harsh punishment. While the corporations take advantage of Neon's lax regulations to endlessly vie for market dominance through espionage and other cutthroat tactics, a number of rival gangs have also flourished in Neon. These include the Seokguh Syndicate, the Ebbside Strikers, and the Disciples. The city is rife with criminal activity.\r\n\r\nDistricts of Neon include Bayu Plaza, Ikuchi Market, Ebbside, Underbelly, and the Spaceport. The Spaceport occupies two small secondary platforms just outside the main Neon platform. The Underbelly consists of the underside of the main platform. Bayu Plaza, Ikuchi Market, and Ebbside are all located on the Upper Platform, with the first two districts inside the enclosed Neon Core section, and the third district encompassing the Upper Platform's exterior.";
            result += "Akila City was founded in 2167 by Solomon Coe, at the site of his first camp on Akila. Solomon named the settlement “Akila City” despite being its only inhabitant at the time because he was confident that other settlers would soon follow him. He was correct, and soon other families, such as the Cartwrights and Hasanovs, arrived at Akila and helped construct Akila City. Akila City grew into a bustling regional hub, and when Solomon engineered an alliance between the Cheyenne and Volii systems, the city was made the capital of Freestar Collective.\r\n\r\nThe oldest part of Akila City is The Core, an elevated and fortified settlement where the founding families built their homes. Since countless Ashta roamed the planet and proved to be a cunning and deadly threat, Akila City had to be walled to keep them out. The center of the settlement was The Rock, which initially served as both a cantina and a meeting hall. Over time, new sets of walls were built around The Core, with the first expansion creating the Midtown district and the spaceport, and the third and most recent expansion creating The Stretch. In 2231, following the creation of the Freestar Rangers by the Council of Governors, the upper floors of The Rock were set aside for the Rangers' use. By 2330, The Core had become an exclusive neighborhood where descendants of the founding families resided, though vacated homes could be sold to outsiders with the approval of the city's historical society. Midtown and Coe Plaza hosted most of the city's businesses, services, and residences, while the poor and unfortunate lived in improvised shacks built in The Stretch.";
            result += "During the early years of the colonization of Alpha Centauri, Gagarin Landing was originally founded as a mining settlement in a canyon on the planet Gagarin. Over time, the mines were abandoned as the settlement grew into a bustling industrial center and dedicated itself to the manufacture of mechs for the United Colonies. When the Colony War ended in 2311 and mech production was banned by the Armistice, Gagarin Landing's mech planets were shuttered and the settlement's economy was gutted. A large number of residents left to find work elsewhere, and most local businesses were forced to close, causing Gagarin Landing to lapse into squalor and crime over the following decade. Around 2320, UC Security officer Dalitso Pretorius was assigned to the settlement's security force and oversaw successful policies to reduce crime levels.\r\n\r\nBy 2330, Gagarin Landing's fortunes finally began to turn. Heavy machinery manufacturer Arc Might purchased the settlement's largest mech plant and refurbished it to produce robotics. Arc Might also promoted Gagarin Landing to other corporations as an ideal location for investment and expansion due to the presence of established infrastructure that could be bought up at rock-bottom prices. Other major corporations operating in the settlement include Reliant Medical, which had set up shop decades earlier and weathered the economic downturn, and Centauri Mills, another recent arrival like Arc Might.\r\n\r\nThe off-world corporations have not been universally welcomed by Gagarin Landing residents. Arc Might is criticized for promising to bring jobs to the settlement, only to immediately automate half of its production facility to keep costs low. Rumors also swirl that the corporations plan significant changes for the settlement's layout, such as building \"priority catwalks\" above the settlement so that corporate employees and executives can avoid mingling with the citizenry. Disgruntled residents have occasionally been known to vandalize corporate structures and steal their property as a means of protest, but UC Security has been careful to prevent tensions from erupting into outright violence.";
            result += "Waggoner Farm is a farm on Montara Luna, Cheyenne System. It is inhabited by Mikaela Waggoner and her father, Waylon Waggoner.\r\n\r\nThey mainly grow grains and root vegetables, rotating between varieties to benefit the soil. They also have livestock and other animals, primarily to keep them fed, although they do sell any excess meat and eggs.";
            result += "New Homestead is a settlement on Titan, a moon of Saturn in the Sol system, and is considered one of the oldest colonies. Initially founded by NASA as the \"Titan Astrobase\" for xenobiology research, it was later transferred to the public as a historical site and is now a tourist destination and settlement. You can find it by navigating to the Sol system, locating Saturn, and then finding the moon Titan, where you will see the New Homestead landing marker. ";
            result += "HopeTown was the first permanent colony to be built on Polvo, which up to that point had been left almost completely undeveloped aside from a handful of hard-scrabble farms. The settlement is the headquarters of starship manufacturer HopeTech, as well as the corporation's main production facility and housing for its employees. HopeTech founder and president Ron Hope manages both the company and the settlement, and holds a seat on the Freestar Collective's Council of Governors. As HopeTown's residents and employees will frequently remind visitors, HopeTown would be nothing without Ron Hope.";
            result += "Paradiso is a luxury beach resort located on the planet Porrima II in the Porrima system. It is run by the Paradiso Group; A cutthroat, cheapskate corporate board and operates outside the jurisdiction of the United Colonies and the Freestar Collective.";


            
            //Factions
            result += "Ecliptic was once a highly-regarded military contractor that accepted contracts from both the United Colonies and the Freestar Collective. These contracts were usually to provide peacekeeping services in far-flung corners of the Settled Systems where the two great factions could not easily deploy their own military forces. Recently, Ecliptic began abusing their nominal authority to extort money under the pretense of enforcing laws, and this has turned the entire Settled Systems against them, even the Crimson Fleet. The UC and Freestar are both aware that Ecliptic has been overstepping its bounds, but they are reluctant to take any action against the organization because they still have need of their services from time to time.\r\n\r\nAs of 2330, Ecliptic mercenaries are known to be willing to work for anyone, as long the client has the credits for their services. They are widely derided as petty killers-for-hire, yet it is an open secret that both the United Colonies and Freestar Collective hire them to handle their dirty work.";
            result += "The Crimson Fleet is not a single organized entity, but a loose confederation of individual pirate captains, all organized under the same banner. For years, the Crimson Fleet was considered a localized criminal problem for the Freestar Collective, but in 2330 the pirates expanded far beyond the Kryx system and established new footholds in Sagan, Cheyenne, Lunara, and Narion. This caused the United Colonies to officially recognize the Crimson Fleet as a growing threat and commit to eliminating it.[2] Members of the Crimson Fleet can be identified by their use of the Jolly Roger, which was adopted as its emblem.[3][2] It is also said that members can never leave once they have joined, and death is the only way out,[4] but pirate captains who managed to amass enough wealth over their careers can buy their way into retirement.\r\n\r\nOver a century ago, the UC had built a super-maximum security prison, The Lock, on the surface of the planet Suvorov in what is today known as the Kryx system, and a star station called The Key above it. In 2241, a prisoner named Jasper Kryx instigated a riot in The Lock, and he and a number of other prisoners managed to break out, seize some ships, and capture The Key. The prisoners began using The Key as a base of operations for pirate raids on UC shipping lanes, and the Crimson Fleet was born. When Jasper died, he left behind a hidden treasure that became known as “Kryx's Legacy”. Later generations of the Crimson Fleet have taken to hunting for this major score, but none have found it yet.";
            result += "The Ebbside Strikers were founded by their future leader, Briggs, and his second-in-command Vogal Fuches. The two were fired from Xenofresh Fisheries and formed the gang by gathering up outcasts and lost souls. They dominated the underbelly of the city, Ebbside, and only killed or mugged when necessary. They consider themselves to be like family and would go to any lengths to protect each other. By 2330, the gang's territory has been greatly diminished by their psychotic rivals, the Disciples. The Strikers now take refuge in Madame Sauvage's Place or else they will be killed by their rivals if they leave.";
            result += "The Freestar Collective was established in 2189, one year after Solomon Coe, the founder of Akila City, invited the Volii system to form an alliance with the Cheyenne system.[2]\r\n\r\nIn 2194, the Narion system voted to join the Freestar Collective after the United Colonies placed The Clinic star station above the planet Deepala and refused to remove it, which was seen as a prelude to annexation. The Freestar Collective mobilized to protect Narion in 2195. The UC escalated by sending a fleet to Narion in 2196, and Freestar responded by sending a fleet of its own, which instigated the Narion War. The conflict persisted until 2216, when both sides signed the Treaty of Narion and Narion was recognized as a Freestar member system.[2]\r\n\r\nThe Freestar Rangers were founded in 2221 to serve as an elite protective and investigative force for the Freestar citizenry.[2]\r\n\r\nThe Freestar Collective built a new farming colony on the planet Vesta in the Lunara system in 2307. The UC objected to this colony in 2308, claiming it was a violation of the Treaty of Narion and Freestar was not permitted to expand to a fourth star system. Diplomatic talks ensued, but ultimately broke down and the UC razed the Vesta colony. This set off a second major conflict, the Colony War, which culminated in the Battle of Cheyenne in 2311. The UC Navy fleet was defeated by a Freestar flotilla of military and civilian ships using hit-and-run tactics.[2]\r\n\r\nBy 2330, a fragile peace between Freestar and the UC remained in place.";
            result += "The federal governing body of the Freestar Collective is the Council of Governors, which currently consists of Mayor Elias Cartwright of Akila City, Administrator Benjamin Bayu of Neon, President Ron Hope of HopeTown, and Dr. Lara Darvish of The Clinic. The Council of Governors only meets periodically in Akila City to address issues that affect the Freestar Collective as a whole. Each member colony has its own political structure and thereby its own method of selecting leaders: the mayor of Akila City is elected by popular vote, Neon and HopeTown are run by the heads of the corporations Xenofresh Fisheries and HopeTech, respectively, and the chief of medicine of The Clinic is appointed. These leaders in turn sit on the Council of Governors representing the interests of the colonies which they lead.\r\n\r\nMilitary and policing duties are divided among three different organizations that fall under the authority of the Council of Governors. The Freestar Militia is the Collective's main military force and acts as a combined army and navy. Freestar Security polices the alliance's member colonies and facilities that opt to permit its presence, and also patrols the orbits of member colonies for contraband smuggling and wanted criminals; of note, Freestar Security is prohibited from landing on Volii Alpha by order of Benjamin Bayu, and Neon operates its own independent security force. Lastly, the Freestar Rangers are an elite investigation and citizen protection force with jurisdiction throughout Freestar territory that answers directly to the Council of Governors.\r\n\r\nAs a libertarian confederation, the Freestar Collective is less cohesive than the United Colonies due to local differences in political structure and social organization. Accordingly, there are also far fewer laws and restrictive regulations in Freestar space, but corruption is rampant in the corporate-administered colonies.";
            result += "The Freestar Rangers were formed in 2231 by the Council of Governors to serve as an elite protective and investigative force for the citizens of the Collective. The Freestar Rangers operate under the Council's direct authority, and outside of cases assigned to them by Council members, they have wide latitude in deciding what matters to investigate and how they conduct patrols.[2][3] While the job is dangerous, the Rangers have forged a formidable reputation over the years, and many criminals will think twice before drawing a gun on a Ranger.\r\n\r\nThe head of the Freestar Rangers holds the title of Marshal, while all other members are simply called Rangers. Prospective members are Ranger Deputies until they complete their on-the-job training. They are headquartered in The Rock.";
            result += "House Va'ruun was formed by the passengers of a colony ship that launched from New Atlantis in 2190 and was reported lost. During one of the colony ship's grav jumps, a passenger named Jinan Va'ruun experienced a period of lost time, during which he claimed to have communed with a celestial being that called itself the Great Serpent. This being asserted that it created the Milky Way galaxy long ago before entering a hibernation lasting countless millennia to recover its strength. Now that it was finally awakening, it would soon reclaim its creation in an event known as the Shrouding. Only its loyal disciples would be permitted to survive, while all others would be devoured. Jinan took on the task of preparing for the Shrouding by spreading the Great Serpent's teachings and gathering as many followers as he could.[2]\r\n\r\nIn 2230, the descendants of the lost colony ship revealed themselves to the Settled Systems as House Va'ruun, a theocratic faction founded and led by Jinan Va'ruun. The ship used to make contact with the other great factions was the Mourning, which served as House Va'ruun's flagship until it was decommissioned in 2299. At first, House Va'ruun established diplomatic relations with the other powers and claimed to only want to spread the message of the Great Serpent. In 2240, however, Jinan declared an all-out war on the rest of human civilization: the Serpent's Crusade. This conflict ended in 2263 when Jinan died and was succeeded by his son Jarek Va'ruun, who sued for peace. House Va'ruun spent the following years trying to rehabilitate its reputation, and even established an embassy in New Atlantis for that purpose, but these efforts largely failed. Following the Colony War, it became the third faction to ratify the Armistice, but then withdrew into isolation.\r\n\r\nFanatical, hostile remnants of House Va'ruun known as Va'ruun Zealots stayed behind and continue to plague the Settled Systems as of 2330. According to Andreja, the Zealots have twisted the teachings of the Va'ruun faith and see all non-believers as “accursed” who must be cleansed from the galaxy before the Great Serpent will deign to consume it. Travelers have reported sightings of Va'ruun Zealots in Decaran, Moloch, Ophion, and Zosma.\r\n\r\nHouse Va'ruun is so secretive that it does not share the jump coordinates of Va'ruun'kai with its own agents. They are sent to gather intel on the United Colonies and the Freestar Collective, as well as pilfer important supplies that House Va'ruun can not produce by itself. These agents are dropped off at random locations and must carry out their missions with practically no support, and they cannot return home until their superiors deem their mission complete and send a ship to retrieve them.";
            result += "As of 2330, the government is managed by the Va'ruun High Council and led by Anasko Va'ruun.\r\n\r\nJinan Va'ruun founded House Va'ruun, which was also based on the four noble Houses he had created: Veth'aal, Ka'dic, Dul'kehf and Ma'leen. Representatives from each of the noble Houses are included in the High Council, smaller subordinate houses cannot have representatives on the High Council.\r\n\r\nAfter the death of Jinan Va'ruun, power passed to his son Jarek Va'ruun, who stopped the Serpent's Crusade started by his father. His brother Jandar Va'ruun headed House Ma'leen and publicly spoke out against the head's decision, calling Jarek Va'ruun a traitor. Conflict led to a rupture and in 2274 House Ma'leen broke ties with House Va'ruun and left Va'ruun'kai, becoming the basis of the Va'ruun Zealots, who refused to obey the decision to stop the Serpent's Crusade. As a result, only three noble Houses remained on the Council.\r\n\r\nEach of the houses that make up the High Council is responsible for a certain sector of government and controls a ministry: Ministry of State — House Veth'aal, Ministry of Conjunction — House Ka'dic, Ministry of Commerce — House Dul'kehf. The Ministry of State is responsible for monitoring compliance with laws and public order, controls the military and police forces. The Ministry of Conjunction deals with external relations and information gathering, including the introduction of agents and communication with them, and contacts smugglers. The Ministry of Commerce deals with economic issues: planning, accounting, and distribution of goods and materials. On the surface, the three noble Houses have no conflict of interest, but in the shadows they compete with each other for resources and influence. The Houses can resolve issues within the competence of their ministries independently, while the High Council resolves more general problems.\r\n\r\nThe Speaker, as a representative of the Great Serpent, has absolute power, and everyone in House Va'ruun is obliged to obey his decisions. All Must Serve.";
            result += "LIST was founded by an unknown person who realized the official settlement authorities of both United Colonies and Freestar Collective are generally overwhelmed with their work and the amount of people who want to leave their homeworlds and begin a new life in an own settlement on a remote planet. Especially in the Stretch in Akila City and the Well in New Atlantis, as well as in industrial colonies like HopeTown and Gagarin Landing, people often wait for months, if not years to get help in foundin a new settlement. And then it is often rather poor help. This lack of help increases the number of criminals in colonies and failed settlers who eventually become Spacers or Crimson Fleet pirates to flee their current situation.\r\n\r\nIt is possible that LIST is a non profit organisation as they seem to have only limited financial resources. Outside of office workers and Settlers, LIST has not many employees and rely on independent help from the outside, to recruit new settler, protect settlements and gather data of habitable planets. Their settlement spaceships are vulnerable to mechanical damage and ships manuels are sometimes not available in common languaes. In case of attacks by spacers and pirates, LIST usually trusts that the settlers can support and defend each other together. This is not always the case, but LIST still provides communication satellites to reach out for help.\r\n\r\nIn general, LIST settlers seem to be very pleased with the services provided by the organisation, even if there are some problems. LIST provides new settlers very quickly and mostly unbureaucratic with a place to life, transport, contact to other settlements, consulting and some material for their new homes. The large number of settlement applications that Phil Hill has to process strongly suggests that LIST is experiencing a high demand.";
            result += "The Sanctum Universum is one of the newest religions to arise among humanity, having formed within the last two decades, but it has grown rapidly in that short time. The core belief of Universals is that God exists somewhere in the universe, and is guiding humanity to meet Him. Universals assert that humanity's invention of the Grav Drive, which facilitates interstellar travel, is evidence of this divine guidance and God's desire to be found.[1]";
            result += "Spacers are scavengers and criminals who usually operate in small, independent groups. They are even less organized than the Crimson Fleet and have no leadership structure or central base. Most of the time, Spacers prefer to loot and occupy abandoned settlements and outposts instead of carrying out aggressive raids, but occasionally they gather in large enough numbers to threaten an entire star system.";
            result += "The Trackers Alliance is a bounty hunter group operating in the Settled Systems.\r\nThe Alliance posts bounties on mission boards, making bounties available to even outsiders looking to earn a living and/or name through bounty hunting. However, there is some level of structure to the group; the Alliance can assign their Agents to specific areas or bounties if needed.\r\n\r\nThe Alliance also has a Bounty Clearance service through their “Trackers Alliance Bounty Clearance Service” kiosk, promising to clear any bounties for a price. This price is usually equal to the bounty incurred with an additional fee.";
            result += "UC System Defense was founded around the 2240s. After the breakout of Jasper Kryx from the Lock, his conquering of KE-725 (the Key), and his creation of the Crimson Fleet, UC Security could no longer contain the threat. As such, the UC Navy was given the duty to destroy the Crimson Fleet. [1]\r\n\r\nThe UC Navy attacked starstation KE-725 with major attacks on at least three separate occasions but ultimately failed to defeat the pirate threat. To try and avoid further damage to the reputation of the Navy, they founded UC SysDef to eliminate the Crimson Fleet.";
            result += "In the final days of the Colony War, the UC Navy's blockade of Akila became the site of a massive fleet engagement. Later dubbed the Battle of Cheyenne, the Freestar Collective's regular Navy attempted to break the blockade in a direct attack, but the superior numbers and ships of the UC Navy fought the Freestar Navy to near defeat. The tide turned in favor of the Freestar Collective by the timely aid of Freestar Civilians piloting their own armed ships and rendering assistance. While the Freestar Collective celebrated this as a joint effort to rout the UC from its territory, the UC Naval commanders were dismayed at both the arrival of additional firepower and the questionable ethics of firing on civilian ships. This, combined with the notification of the escalating crisis on Londinion, forced the UC Navy to abandon the blockade.[4] As such, it became a pyrrhic victory for the Freestar Collective: they won the engagement, but only through a significant loss of ships and sacrifices made by civilian captains. .[2][5] While controversial, the addition of the Freestar Civilian ships undeniably turned the tide of the Battle of Cheyenne in favor of the Collective, leaving the UC Navy looking for options on how to match or exceed such an addition in future conflicts.\r\n\r\nFrom this, the UC approved the creation of their own civilian fleet in 2315 to support their regular Navy, with two major differences: Captains would need to voluntarily enlist, thereby becoming an extension of the official UC Military, and second, that the entirety of the Vanguard would become its own branch of the UC Military structure.[2] With these conditions in place, the UC Navy Vanguard is a privateer force with less direct support than the regular Navy but also fewer restrictions and greater autonomy than the regular military. Additionally, in exchange for service, Vanguard Captains could earn UC citizenship as well as considerable bonuses upon enlistment, mission completion, and meritorious award.";
            result += "In keeping with Naval tradition, Vanguard officers receive the initial title of \"Captain\" as the commanding officer of their vessel, though career Vanguards may attain higher, official ranks in the UC Navy command structure.\r\n\r\nThe Vanguard is tasked with various duties, including taking the fight to the Crimson Fleet after its great rise in power.[6] For the most part, the duties of the Vanguard are \"as needed\", ranging from taking down hostile spacecraft,[7] to aiding the Science division of MAST with an invasive species,[3] to filling in the gaps which the UC Navy itself cannot fill.[8] UC Vanguard Recruits are sometimes also tasked with checking in on abandoned military structures.[9]\r\n\r\nAs of 2330, the fastest and simplest way to earn UC citizenship was through service in the Vanguard,[10] where one could earn citizenship after as fast as three years, to as late as twenty years of service.[3] New recruits are tasked with passing a flight simulator, after which they have to swear an oath and are sent out on a probationary mission.[11] After completion of the mission, the aspirant officially joins the Vanguard and is awarded their uniform.[12]";
            result += "\"The motto of the Vanguard is \"Supra et Ultra\" — above and beyond. That is where we serve — beyond the furthest reaches of the United Colonies military, and with honor and duty above reproach. Do you swear to protect and defend the citizens of the United Colonies, to the best of your abilities and to uphold the values of the Vanguard — honor, loyalty, self-reliance — in all your actions as a member of the United Colonies Navy?\"";
            result += "The United Colonies (abbreviated as UC) is the first interstellar government to have formed in the Settled Systems. It is a centralized republic, and controls the star systems Alpha Centauri, Sol, Toliman, and Wolf. The UC's capital is the city of New Atlantis on the planet Jemison in the Alpha Centauri system which was founded in 2160,[1] becoming the official capital a year later";

            //Lore
            result += "In the year 2150 scientists discovered that the magnetosphere of Earth would collapse in the near future, and so unity was required to save humanity by journeying to the stars. This union would become known as the United Colonies.[3]\r\n\r\nThe United Colonies was formed in 2159 on Earth,[4] three years after space exploration had already led to the Alpha Centauri star system.[1] In 2160 the first colony ship landed on the planet Jemison - marking the de facto start of the United Colonies outside of Earth.[3]\r\n\r\nDedicated to the exploration and colonization of space through cooperation and harmony, and to allow the people further freedom in settling of planets, the Centaurus Proclamation was issued in 2161 - the same year as the colonization of Jemison. The proclamation enabled colonization outside of the United Colonies,[4] resulting in the formation of the Freestar Collective in 2188 and the eventual formation of House Va'ruun in 2230.[5]\r\n\r\nIn 2203, Earth officially became uninhabitable. In a response, the United Colonies declared itself the keepers of artifacts, ideals, cultures and peoples of Earth.[4]";
            result += "Narion War\r\nIn 2194, tensions started to rise between the United Colonies and Freestar Collective as a result of the United Colonies bringing The Clinic station to the Narion system - without the approval of the locals. Requests by the locals to remove the ship were not answered by the United Colonies, which led them to join the Collective.[2] This led to a war which lasted from 2196 to 2216.[2] While the United Colonies won a decisive military victory, tensions back in its own home territory forced it to back down - resulting in the signing of the Treaty of Narion.";
            result += "Serpent's Crusade\r\nBack in 2230, House Va'ruun had made itself known to the Settled Systems after years of being missing. A theocracy dedicated to their god - the Great Serpent. House Va'ruun was peaceful and spread the word of their faith throughout the settled systems.[8] This would change a decade later, when the House declared war against the rest of the galaxy, initiating the Serpent's Crusade. After 23 years of fighting, the founder of the House died. His son, Jarek Va'ruun, sued for peace.[9]\r\n\r\nNot all of House Va'ruun would accept peace, however, and continue their fight against those who do not follow their faith. These people would become known as the Va'ruun Zealots.[9]";
            result += "Colony War\r\nIn the year 2307, the Freestar Collective established a mining outpost on the planet of Vesta in the Lunara system.[2] The United Colonies claimed this classified as colonization,[10] while the Freestar Collective claimed it was merely an outpost. Diplomatic talks fail to resolve the matter, causing the Colony War to break out in 2308.[11][2] The war ends in 2311, after the Freestar Collective achieves a pyrrhic victory during the Battle of Cheyenne.[2] A peace treaty known as the Armistice was signed to officially end the war.[10][12]";
            result += "The government of the United Colonies is known as the Military, Administrative and Scientific Triumvirate, often abbreviated to just \"MAST\".[13] Each division is equal, and works together to further the cause of the United Colonies.[14]\r\n\r\nSome critique the United Colonies for having too many laws, however the laws and regulations within the UC are part of the cause of the welfare of its citizens.[15]\r\n\r\nCitizenship\r\nWithin the United Colonies citizenship is always an earned through service, with even those who are born under UC citizens having to earn their own citizenship.[16][17] Citizenship can be earned through service to any of the three branches of MAST,[18] though the scientific and administrative positions are typically more competitive than their military counterpart, a result of most people being unwilling to go to combat.[14]\r\n\r\nHowever, even those who are not citizens yet can still get some benefits from being born a United Colonies native. Children between the ages of five to eighteen can be enrolled in a schooling system, where they are taught art, science, mathematics, history, civics,[18] and more.[19]\r\n\r\nUC natives are better paid in military service than their non-native counterparts. By contrast, natives are more likely to get larger bounties for crimes committed outside UC territory.[20]\r\n\r\nWithin the UC, citizenship is considered a strong badge of loyalty and dedication. Upon becoming a citizen people are provided with an ID card, welcome letter by the president, discounts at UC businesses, and a one-time credit disbursement.[16][17] Those who prove themselves especially dedicated to the United Colonies can be appointed as a \"Class One Citizen\". These are provided with housing, a greater discount at UC businesses, and a larger credit disbursement.[21][22]";


            //Corps
            result += "Advanced Nutrition seems to specialize at producing packaged ready-to-eat food items and drinks.";
            result += "Arc Might is one of the galaxy's premier heavy equipment firms and one of the corporations \"revitalizing\" Gagarin Landing, in the wake of the Armistice agreement which outlawed mechs, the city's original industry.";
            result += "Allied Armaments focuses almost exclusively on military-grade weapons for use in combat zones. As such, they eschew the plastics and complex laser options for more rugged construction types, leaning more heavily into traditional ballistics, metal, and durable ceramics.";
            result += "Arboron specializes at producing particle beam and electromagnetic weapons. It is a subsidiary of Ryujin Industries and their office/shop can be accessed in the Ryujin Tower in Neon.";
            result += "Argos Extractors is an interstellar mining corporation";
            result += "The company CAN-uck! specializes at producing various canned foods. The name basis of \"Canuck\" and the maple leaf iconography indicates a Canadian heritage to the branding. Various products harken back to traditional and stereotypical foodstuffs from Canadian society.";
            result += "Centauri Mills produces various kinds of sweets and grain-related products. One of their facilities has been operating on Gagarin since shortly after the Armistice, which lead to the decommission of the Mech factory in Gagarin Landing and opened up opportunities for other corporations to move in.";
            result += "Chunks is a brand of food products in the Settled Systems. Its main product, the titular Chunks, are small artificial cubes made to resemble various foods and beverages.";
            result += "CombaTech produces weaponry on the planet Jemison; as such, they are one of the United Colonies' major suppliers of civilian and peacekeeper-grade weaponry, and their weapons are nearly ubiquitous in the hands of UC Security, Navy, and Marine units. A marriage of the complex manufacturing power and the relative plentifulness of materials engineering, CombaTech weapons are generally cheap and efficient options for casual use and security forces.\r\n\r\nDue to their affordability and widespread availability their weapons are commonly used by most factions, including Spacers, Ecliptic, and (to a lesser extent) Crimson Fleet units early in the game. The Grendel and Beowulf models are among the most frequently used or lootable items and can provide a modest stream of sales income and 7.77mm ammunition.\r\n\r\nCombaTech weapons favor cheaper materials in grips, stocks, barrels and casings, with visible plastics and ceramics on most of their weapons. In some cases, like the Equinox, this is an advantage, as skilled weaponsmiths may remove the standard cover (with no detrimental effects) to install Amplification modules for more powerful discharges.\r\n\r\nLike most manufacturers in the game, CombaTech trends toward a specific market demographic -- in this case, frugality and utility -- with the exception of certain weapons like the Hard Target or the Big Bang that have higher damage and expense. This makes CombaTech weapons on the whole less useful in protracted combat situations against hardened and powerful opponents, where civilian and peacekeeper-grade weapons are less suited than military-grade options.";
            result += "The Galactic Banking Consortium, or GalBank, is an apolitical financial corporation operating throughout the Settled Systems.\r\n\r\nGalBank ATMs can be hacked to steal credits.";
            result += "HopeTech was founded by Ron Hope, a former blue collar deep space hauler who spent his life savings to establish a company dedicated to making sturdy, dependable cargo freighters that prioritize function over form. None of HopeTech's ships are elegant or excel in combat situations, but they are generally more affordable than their competition. They can haul vast amounts of cargo, and they are known to be as reliable on their 300th flight as on their first. The corporation constructed HopeTown, which combined employee housing and amenities, a starship factory, and a corporate headquarters into a single settlement, on the planet Polvo in the Valo system. It cementing its image as a business that treated both its customers and its employees like family. HopeTech grew rapidly, and in time Ron Hope attained a seat on the Freestar Collective's Council of Governors.\r\n\r\nAs of 2330, HopeTech was consistently outperforming its sales targets, but this was not always the case. As recently as 2328, HopeTech had been suffering a series of consecutive quarterly financial losses, and industry observers were convinced that the company was on the verge of insolvency and dissolution. The fact that HopeTech's fortunes managed to turn around so quickly was considered a testament to Ron Hope's leadership.\r\n\r\nBehind his blandly congenial public persona, however, Ron Hope was a cutthroat profiteer. In a bid to diversify HopeTech's portfolio, Ron attempted to produce a fertilizer for crops and advertised it to Freestar settlers. The fertilizer was disastrous for these farmers, as it killed their crops, but it also had the side effect of catalyzing mineral formation in the soil. Rather than recall the product, Ron continued to sell it to farmers, waited for their farms to fail, and then hired the First Cavalry to force the farmers to sell their land to HopeTech cheaply. HopeTech would then reap the mineral-rich land for raw material that could be used to manufacture HopeTech's ships. This saved HopeTech a substantial amount of money and allowed it to produce more ships than ever. HopeTech's underhanded methods were uncovered by the Spacefarer in their capacity as a deputy of the Freestar Rangers in 2330. Regardless of whether the Spacefarer exposed Ron Hope's crimes or accepted his bribe to keep silent, the president of HopeTech met his demise soon afterward.";
            result += "Kore Kinetics differentiates itself from other weapons manufacturers in both the appearance of its weapons and the ammunition used. The exterior of the weapons is designed in such a way that it appears unfinished, however the weapons themselves do a fair bit of damage. As these weapons are the only ones to make use of the .50 MI Array, .43 MI Array, and 6.5mm MI Array, getting new ammunition for these weapons can be more difficult than for the more conventional weapons produced by the other weapon manufacturers.";
            result += "Laredo weapons have a distinctive, \"wild west\" appearance compared to weapons from most other manufacturers, often utilizing materials like wood and polished steel in their construction. As the company is based out of Akila, Laredo-made weapons are commonly found in Freestar Collective space.[1]";
            result += "The Paradiso Group is the owner and operator of the independent luxury resort Paradiso, located on Porrima II in the Porrima system. All of the Paradiso Group's executives live on the resort grounds. The group is lead by a board and holds it's meetings in an office inside the Paradiso hotel. However, only three board members show up regularly for meetings.";
            result += "Protectorate Systems is a ship module manufacturer in Starfield that specializes at producing cargo modules.";
            result += "Red Harvest produces various kinds of grain-related products, including grain-based liquors.";
            result += "Reliant Medical is the largest medical provider in the Settled Systems. They have spent decades advancing medical science and building a complex supply network.";
            result += "Ryujin Industries is a megacorporation that offers its products throughout the Settled Systems. Its headquarters is Ryujin Tower, located in the pleasure city of Neon.Ryujin Industries is based in the city of Neon on Volii Alpha in the Volii system. The company is led by CEO Masako Imada, with other notable members being Imogene Salzo, the primary point of contact and quest giver for the player. The quests given to the player by Ryujin revolve around corporate espionage and focus on undermining Ryujin's competitors and giving the company an edge in the industries it is involved with. Ryujin Industries has a number of subsidiaries across multiple economic sectors such as drone, weapons, and ship manufacturing. It is implied that Ryujin Industries is one of the largest corporations in the Settled Systems. The company is demonstrated to have an immense amount of influence over the local authorities, Administrator Benjamin Bayu, and the Freestar Collective allowing them to skirt certain regulations and avoid responsibility for their actions.";
            result += "Slayton Aerospace is a manufacturer of ship systems, specifically engines and Grav Drives. The corporation's headquarters occupies a floor of the Trade Tower in Neon, and its CEO is Nicolaus Slayton.";
            result += "TerraBrew Coffee, also stylized as Terrabrew, is a café in New Atlantis, with branches also operating in Akila City and Neon.\r\n\r\nThere are two branches in New Atlantis, with the main one being in the Spaceport and another in the Commercial District. Cups of various TerraBrew coffee types can also be found throughout the game and serve as Aid items, restoring a small amount of health and sometimes providing other benefits. Empty TerraBrew cups and lids are also common junk items scattered over basically any major settlement, further pointing at the popularity of the brand.\r\n\r\nOne of the locations where Terrabrew baristas are trained is the Barista Sciences Institute (BSI).\r\n\r\nThe standard procedure when a superior product is discovered by Terrabrew, but not the competition or customers, is its destruction — provided that the costs are too high for Terrabrew to incorporate it.\r\n\r\nTerrabrew has a corporate policy that requires its baristas to state that every product Terrabrew offers is their favorite, as long as state that it's the corporate policy to say so.";
            result += "Tranqulitea is a brand of tea available throughout the Settled Systems. It is a subsidiary of Ryujin Industries and as such, their offices can be accessed in the Ryujin Tower in Neon.";
            result += "While the Trade Authority claims to be entirely apolitical and involved only in legal trade and shipping, they have a checkered reputation and are openly suspected of profiteering, theft, and smuggling. However, while the group has been investigated and even brought to trial on occasion, any witnesses to their wrongdoing always end up recanting their testimony.\r\n\r\nTrade Authority offices and kiosks can be found at numerous spaceports and star stations. Notably, Trade Authority representatives will readily purchase contraband and stolen items.";
            result += "Trident Luxury Lines is a corporation that offers premium interstellar vacation packages, and maintains its own fleet of custom-built passenger liners for that purpose. Any Trident employee will readily admit that their ships are expensive and cannot compete with other staryards' products in terms of defenses and firepower, but they insist that a flight aboard a Trident ship is an unparalleled luxury experience and more than worth the price. Vacation packages on Trident liners are extremely popular, even with their exorbitant cost, and are usually booked by customers as quickly as openings become available.\r\n\r\nTrident ships and ship parts are unavailable for purchase by consumers, and according to Jia Chen, all vacation packages have been booked for the foreseeable future. Award-winning ship designer Gladys Coffin heads Trident's R&D department at Trident Staryard, the corporation's main manufacturing facility, and is responsible for creating renowned ship models such as the Astra.";
            result += "In the late 22nd century, Xenofresh Fisheries discovered the aquatic planet Volii Alpha in the Volii system and set up a fishing platform on the planet. Not long afterward, Xenofresh discovered that one of Volii Alpha's native species, the Chasmbass, produced secretions that caused an addictive hallucinogenic effect in humans, but had no apparent harmful side effects. Medical authorities approved this drug, which named Aurora, for human use, but the United Colonies promptly banned it within its territory. This resulted in an influx of tourists to the Xenofresh platform, and Xenofresh Fisheries realized that they could make more profit from Aurora than from catching and selling fish alone. In 2187, Xenofresh transformed the platform into the pleasure city of Neon, where the Aurora flowed freely. After Volii joined the Freestar Collective in 2189, Aurora's sale and consumption was officially restricted to the confines of Neon.\r\n\r\nAs of 2330, Xenofresh Fisheries continues to control Neon and the planet Volii Alpha under the leadership of its CEO, Benjamin Bayu, who has decreed that Aurora may only be distributed legally through Boone Morgan at the Astral Lounge club in Neon's Trade Tower. As Xenofresh owns both the Trade Tower and the Astral Lounge, this arrangement gives Xenofresh a monopoly over the legal Aurora trade. Outside Neon, Aurora smuggling is a persistent problem despite the best efforts of Neon Security and the Freestar Rangers to contain it. Xenofresh Fisheries also continues to carry out its original work by fishing the seas of Volii Alpha and producing food that is eaten across the Settled Systems.";

